// Step 1: Search for nodes related to specimen, aliquot, individual
const keywords = ["specimen", "aliquot", "individual", "sample"];
const results = {};
for (const kw of keywords) {
  const r = await tools.graph_search_nodes({ expression: kw, pageSize: 50 });
  results[kw] = r;
}
return results;
